import{_ as e,o,c as t,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Developer Summit - BlueStore Part 2","description":"","frontmatter":{"title":"Ceph Developer Summit - BlueStore Part 2","date":"2025-09-11T00:00:00.000Z","updated":"2025-09-12T00:00:00.000Z","tags":["Ceph","BlueStore","分布式存储","性能优化","Erasure Coding"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_Developer_Summit_-_BlueStore_Part_2.md","filePath":"posts/2025/Ceph_Developer_Summit_-_BlueStore_Part_2.md","lastUpdated":1780459816000}'),a={name:"posts/2025/Ceph_Developer_Summit_-_BlueStore_Part_2.md"};function i(n,r,s,g,u,h){return o(),t("div",null,[...r[0]||(r[0]=[l('<h3 id="ceph-开发者峰会-bluestore-第二部分会议纪要" tabindex="-1"><strong>Ceph 开发者峰会 - BlueStore 第二部分会议纪要</strong> <a class="header-anchor" href="#ceph-开发者峰会-bluestore-第二部分会议纪要" aria-label="Permalink to &quot;**Ceph 开发者峰会 - BlueStore 第二部分会议纪要**&quot;">​</a></h3><h4 id="会议时间" tabindex="-1"><strong>会议时间</strong> <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;**会议时间**&quot;">​</a></h4><p>（未明确提及，假设为近期开发会议）</p><h3 id="_1-主要议题与讨论内容" tabindex="-1"><strong>1. 主要议题与讨论内容</strong> <a class="header-anchor" href="#_1-主要议题与讨论内容" aria-label="Permalink to &quot;**1. 主要议题与讨论内容**&quot;">​</a></h3><h4 id="_1-1-vm-provisioning-插件开发" tabindex="-1"><strong>1.1 VM Provisioning 插件开发</strong> <a class="header-anchor" href="#_1-1-vm-provisioning-插件开发" aria-label="Permalink to &quot;**1.1 VM Provisioning 插件开发**&quot;">​</a></h4><ul><li><strong>目标</strong>：开发类似 <code>video</code> 插件的低层内核设备级功能，支持硬件压缩，以减轻 CPU 负载。</li><li><strong>关键点</strong>：需要新增统计信息报告，例如设备实际容量与逻辑提交数据量的对比。</li></ul><h4 id="_1-2-ec-erasure-coding-优化提案" tabindex="-1"><strong>1.2 EC（Erasure Coding）优化提案</strong> <a class="header-anchor" href="#_1-2-ec-erasure-coding-优化提案" aria-label="Permalink to &quot;**1.2 EC（Erasure Coding）优化提案**&quot;">​</a></h4><ul><li><strong>问题</strong>：当前克隆操作在 EC 场景下性能较差。</li><li><strong>提案</strong>：新增专用对象操作，支持数据块对齐移动；探索预计算机制，如压缩/CRC 在 Primary OSD 完成，再同步至副本。</li><li><strong>挑战</strong>：需验证技术可行性，可能无法在短期（Umbrella 版本）实现。</li></ul><h4 id="_1-3-blue-store-功能改进清单" tabindex="-1"><strong>1.3 Blue Store 功能改进清单</strong> <a class="header-anchor" href="#_1-3-blue-store-功能改进清单" aria-label="Permalink to &quot;**1.3 Blue Store 功能改进清单**&quot;">​</a></h4><ul><li><p><strong>已关联 PR 的议题</strong>：</p><ul><li><strong>RocksDB 缓存优化</strong>：修复因大缓存条目导致的频繁驱逐问题。</li><li><strong>零值支持</strong>：区分未映射区域与零值区域，提升 EC 数据分片效率。</li><li><strong>非 4KB 页支持</strong>：解决 PowerPC（64KB 页）下 Buffered/Direct Write 冲突问题。</li><li><strong>快速恢复</strong>：优化大容量磁盘的 OSD 重启时间。</li><li><strong>Scrub 优化</strong>：支持重压缩、碎片整理及节点元数据修复。</li><li><strong>BlueFS 分配映射持久化</strong>：优化高碎片化磁盘的存储效率。</li></ul></li><li><p><strong>待评估议题</strong>：</p><ul><li><strong>CPU Trace 工具</strong>：用于性能优化验证。</li><li><strong>默认定位器切换至 Hybrid BT2</strong>：需更多测试与 QA 验证。</li></ul></li></ul><h4 id="_1-4-其他讨论" tabindex="-1"><strong>1.4 其他讨论</strong> <a class="header-anchor" href="#_1-4-其他讨论" aria-label="Permalink to &quot;**1.4 其他讨论**&quot;">​</a></h4><ul><li><strong>性能优化方向</strong>：重构代码，如内存分配优化、PMR 容器应用；通过 CPU Trace 工具精确测量微优化效果。</li></ul><h3 id="_2-决议事项" tabindex="-1"><strong>2. 决议事项</strong> <a class="header-anchor" href="#_2-决议事项" aria-label="Permalink to &quot;**2. 决议事项**&quot;">​</a></h3><ol><li><p><strong>优先推进</strong>：</p><ul><li>VM Provisioning 插件的硬件压缩支持及相关统计功能。</li><li>RocksDB 缓存优化、非 4KB 页支持、快速恢复等已关联 PR 的改进。</li></ul></li><li><p><strong>进一步研究</strong>：</p><ul><li>EC 数据移动操作的可行性（长期优化）。</li><li>零值支持对 EC 校验分片的影响。</li></ul></li><li><p><strong>工具链完善</strong>：将 CPU Trace 工具纳入开发流程，辅助性能优化验证。</p></li></ol><h3 id="_3-后续行动计划" tabindex="-1"><strong>3. 后续行动计划</strong> <a class="header-anchor" href="#_3-后续行动计划" aria-label="Permalink to &quot;**3. 后续行动计划**&quot;">​</a></h3><p>| <strong>任务</strong> | <strong>负责人</strong> | <strong>时间节点</strong> | |||--| | 提交 VM Provisioning 插件 PR | （未明确） | Umbrella 版本 | | 评估 Hybrid BT2 定位器性能 | QA 团队 | 下一测试周期 | | 完善 Fast On Recovery 方案 | Adam/开发团队 | 短期迭代 | | 组织零值支持技术讨论 | Adam/Bill/Alex | 近期会议 |</p><h3 id="_4-待解决问题" tabindex="-1"><strong>4. 待解决问题</strong> <a class="header-anchor" href="#_4-待解决问题" aria-label="Permalink to &quot;**4. 待解决问题**&quot;">​</a></h3><ul><li>EC 预计算机制对集群一致性的潜在影响。</li><li>硬件压缩插件的兼容性测试（不同设备厂商）。</li></ul><p><strong>备注</strong>：会议未明确部分事项的负责人，需在后续跟进中确认。</p><p>以上内容是对 Ceph 开发者峰会 - BlueStore 第二部分会议纪要的改进总结，确保了会议关键细节的准确反映，并保留了相关领域的英文关键词。</p>',20)])])}const p=e(a,[["render",i]]);export{d as __pageData,p as default};
